const data = $json.body;

return [{
  json: {
    departureLocation: data.departureLocation || "Not provided",
    destination: data.destination || "Not specified",
    budget: data.budget || "~",
    tripType: data.tripType || "N/A",
    groupSize: data.groupSize || "1",
    ageRange: data.ageRange || "~",
    startDate: data.startDate || "N/A",
    endDate: data.endDate || "N/A",
    email: data.email || "unknown"
  }
}];

const {
  destination,
  customDestination,
  startDate,
  endDate,
  budget,
  tripType,
  groupSize,
  ageRange,
  email,
  departureLocation
} = $json;

const finalDestination = customDestination || destination;

return [{
  json: {
    email,
    prompt: `You are a helpful travel agent. A user is planning a trip and needs your help creating a detailed itinerary.

- Departure location: ${departureLocation || "Not provided"}
- Destination: ${finalDestination}
- Travel dates: ${startDate} to ${endDate}
- Budget: $${budget}
- Trip type: ${tripType}
- Group size: ${groupSize}
- Age ranges: ${Array.isArray(ageRange) ? ageRange.join(", ") : ageRange || "not specified"}

Create a complete itinerary for this trip. Include recommendations for:
1. Flights (airlines and routes from ${departureLocation || "the nearest major airport"})
2. Accommodation options
3. Daily schedule with activities
4. Local food spots
5. Transportation and travel tips

Respond in a clean and organized layout with sections.`
  }
}];

const travel = $node["Prepare Travel Data"].json;
const ai = $node["OpenAI"].json.message?.content || "No itinerary found.";

return [
  {
    json: {
      destination: travel.destination,
      departureLocation: travel.departureLocation,
      startDate: travel.startDate,
      endDate: travel.endDate,
      groupSize: travel.groupSize,
      budget: travel.budget,
      email: travel.email,
      itinerary: ai
    }
  }
];
